Этот фрагмент — не пример грамматики, а собственный синтаксис правил ISPA, записанный на ISPA. Генератор самоприменим (self-hosted): тот же DSL, которым описывают C или JSON, достаточно выразителен, чтобы описать самого себя.
Несколько примитивов, чтобы читать его:
@
помечает точку захвата (capture point) — начинающийся там фрагмент становится доступен семантическому действию. Это механизм тегирования TDFA, проявляющийся прямо в синтаксисе грамматики, а не прикрученный сверху.
{...}
— семантическое действие.
{@}
— это сокращение для “вернуть единственный захват как есть”; используется в листовых правилах вроде
ID
,
STRING
или
QUANTIFIER
, которые просто возвращают совпавший текст.
@{field1, field2}
строит узел AST прямо из именованных захватов — без отдельного кода построения дерева. Действие
@{name, v}
в правиле
rule
означает: “узел, который порождает это правило, имеет поле
name
(из захвата
ID
) и поле
v
(из повторяющихся захватов
#value
)”. Именно это на практике означает “автоматический AST”: форма действия — это и есть форма узла.
#name:
объявляет вложенное, локально-ограниченное правило — видимое только внутри содержащего его правила.
#value
,
#pattern
,
#capture
и подобные существуют только внутри
rule
;
#pattern
,
#STRING
и аналогичные — только внутри
#value
. Это не даёт служебным внутриграмматическим правилам засорять глобальное пространство имён, вместо того чтобы заставлять каждое правило генератора жить на верхнем уровне.
Стандартные regex-подобные операторы работают как обычно:
+
(один или более),
*
(ноль или более),
?
(опционально),
|
(альтернатива), и строковые литералы в кавычках для точного текста.
\s
— встроенный токен пропуска пробелов.
Читая сверху вниз:
ID
совпадает с идентификатором (буква, затем буквы/цифры/подчёркивание).
rule
— это имя, двоеточие, одно или более
#value
, и терминатор — где каждый
#value
представляет собой
#pattern
(ссылку на
ID
, строку, пробел, или заключённую в скобки
#group
), за которым опционально следуют альтернативы и квантификатор.
main
— это просто точка входа: файл грамматики — это одно или более правил.
Проще код для взаимодействия с парсером я представить не могу:
#include <Parser.h>
#include <iostream> // output to console
#include <fstream> // output to file

int main(int argc, const char** argv) {
 if (argc < 2) {
 std::cout << "Usage: " << argv[0] << " \"<input>\"\n";
 return 1;
 }
 Parser::Lexer lexer;
 lexer.makeTokens(argv[1]);
 Parser::Parser parser;
 Parser::Types::main &node = parser.parse(lexer);
 std::ofstream of("tree.txt");
 of << node << "\n\n";
}
Как выглядит сгенерированный парсер
// Parser.h
#ifndef PARSER_H
#define PARSER_H
#include <string>
#include <vector>
#include <unordered_map>
#include <array>
#include <string>
#include <variant>
#include <optional>
#include <memory>
#include <ispastdlib.hpp>
namespace Parser {
	enum class Tokens { // Все имена токенов. Полезно для switch
 NONE,
 AUTO_5,
 AUTO_4,
 AUTO_2,
 AUTO_1,
 AUTO_3,
 rule_value_STRING,
 __WS,
 rule_value_SPACE,
 NUMBER,
 AUTO_0,
 rule_value_QUANTIFIER,
 ID,
	};
	enum class Rules { // аналогично
 NONE,
 main,
 rule_value_alternative,
 rule_value_pattern,
 rule_value_group,
 rule_value,
 rule_capture,
 rule,
	};
	namespace FlatTypes { 
 /*
 а тут уже все типы - структуры, которые создаються в грамматике через @
 автоматически создает std::shared_ptr для само-вызывающихся структур
 shared_ptr легче использовать из-за возможности копирования.
 unique_ptr в текущей архитектуре не даст скомпилировать код, 
 а фикс требует редактирования фундамента
 */
 struct AUTO_5;
 struct AUTO_4;
 struct AUTO_2;
 struct AUTO_1;
 struct AUTO_3;
 struct rule_value_STRING;
 struct rule;
 struct rule_value;
 struct __WS;
 struct rule_value_SPACE;
 struct NUMBER;
 struct AUTO_0;
 struct rule_value_QUANTIFIER;
 struct ID;
 struct main;
 struct rule_value_alternative;
 struct rule_value_pattern;
 struct rule_value_group;
 struct rule_capture;
	}
	namespace FlatTypes {
 struct AUTO_5 {
 auto write_to_output(::ISPA_STD::ASTPrinter<std::ostream>& printer) const -> void;
 auto print(std::ostream& os) const -> void;
 auto to_string() const -> std::string;
 };
 auto operator<<(std::ostream &os, const AUTO_5 &value) -> std::ostream&;
	}
	namespace FlatTypes {
 struct AUTO_4 {
 auto write_to_output(::ISPA_STD::ASTPrinter<std::ostream>& printer) const -> void;
 auto print(std::ostream& os) const -> void;
 auto to_string() const -> std::string;
 };
 auto operator<<(std::ostream &os, const AUTO_4 &value) -> std::ostream&;
	}
 // ...
 namespace FlatTypes {
 struct rule_value_group {
 std::vector<::ISPA_STD::Node<::Parser::Rules, std::shared_ptr<::Parser::FlatTypes::rule_value>>> value;
 auto write_to_output(::ISPA_STD::ASTPrinter<std::ostream>& printer) const -> void;
 auto print(std::ostream& os) const -> void;
 auto to_string() const -> std::string;
 };
 auto operator<<(std::ostream &os, const rule_value_group &value) -> std::ostream&;
	}
 // ...
 // вариант из всез токенов. Лексер буквально сохраняет std::vector<Token>
 // c этим же std::vector работает и парсер
 using Token = std::variant<std::monostate, ::ISPA_STD::Node<::Parser::Tokens, Types::AUTO_5>, ::ISPA_STD::Node<::Parser::Tokens, Types::AUTO_4> ...>;
	class Lexer : public ::ISPA_STD::Lexer_base<::Parser::Tokens, Token> {
 static ::ISPA_STD::DFA::API::CharToClass char_class_table;
 static ::ISPA_STD::DFA::API::Table<21, 129> dfa_table; // сама DFA таблица
 /*
 Тут лежат действия для сохранения значений.
 в DFA таблице закодированны как dfa.size() + action_table_state_id
 */
 static ::ISPA_STD::DFA::API::Table<211, 4> action_table;
 /*
 А это и есть большая switch функция, позволяющая выполнить что угодно во время
 лексического анализа
 Пока что отвечает за создание финальных AST структур токена
 */
 static auto semantic_action_exec(long long state, const ::ISPA_STD::DFA::API::Captures& captures, long long start_pos, const char* start, long long length, long long line) -> std::pair<long long, Token>;
 bool init_done;
 auto init() -> void override;
 ::ISPA_STD::DFA::API::TdfaLayout<14, 14> tdfa_registers;
 static std::array<::ISPA_STD::DFA::API::DFADebug, 226> debug_array;
 static std::unordered_map<long long, std::unordered_map<long long, long long>> debug_index;
	public: 
 auto makeToken(const char*& pos) -> Token override;
	};
 class Parser : public ::ISPA_STD::LLParser_base<::Parser::Tokens, ::Parser::Rules, Types::main, Token> {
 // ...
 /*
 Одно из правил сгенерированного парсера
 IT - итератор, позволяющий делать lazy parse.
 Lazy parrsing - аккамуляция токенов по мере надобности парсером.
 Много ненужного кода. Чтобы его убрать нужен оптимизатор, на что я решил
 пока что время не тратить. В целом компилируемые языки сделают больше
 чем весь возможный оптимизатор вместе взятый
 */
 template<typename IT>
 auto rule_value_pattern(IT pos) -> ::ISPA_STD::MatchResult<Rules, Types::rule::value::pattern, IT>{
 std::variant<std::monostate, ::ISPA_STD::Node<::Parser::Rules, Types::rule::value::group>, ::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::SPACE>, ::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::STRING>, ::ISPA_STD::Node<::Parser::Tokens, Types::ID>> _0;
 bool success_1;
 success_1 = false;
 // grammar `@ ( ID | rule::value::STRING | rule::value::SPACE | rule::value::group)`: choice; reset match status before selecting an alternative
 success_1 = false;
 switch (static_cast<Tokens>((*pos).index())) {
 case Tokens::AUTO_1: {
 ::ISPA_STD::MatchResult<Rules, Types::rule::value::group, IT> rule_value_group_2;
 bool success_3 = false;
 rule_value_group_2 = rule_value_group(pos);
 if (!(rule_value_group_2.status)) {
 return {};
 }
 success_3 = true;
 pos = rule_value_group_2.it;
 if (!success_3) {
 return {};
 }
 _0 = rule_value_group_2.node;
 success_1 = true;
 break;
 }
 case Tokens::ID: {
 ::ISPA_STD::Node<::Parser::Tokens, Types::ID> ID_4;
 bool success_5 = false;
 if (!(std::holds_alternative<::ISPA_STD::Node<::Parser::Tokens, Types::ID>>((*pos)))) {
 return {};
 }
 ID_4 = std::get<::ISPA_STD::Node<::Parser::Tokens, Types::ID>>((*pos));
 success_5 = true;
 pos++;
 if (!success_5) {
 return {};
 }
 _0 = ID_4;
 success_1 = true;
 break;
 }
 case Tokens::rule_value_SPACE: {
 ::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::SPACE> rule_value_SPACE_6;
 bool success_7 = false;
 if (!(std::holds_alternative<::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::SPACE>>((*pos)))) {
 return {};
 }
 rule_value_SPACE_6 = std::get<::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::SPACE>>((*pos));
 success_7 = true;
 pos++;
 if (!success_7) {
 return {};
 }
 _0 = rule_value_SPACE_6;
 success_1 = true;
 break;
 }
 case Tokens::rule_value_STRING: {
 ::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::STRING> rule_value_STRING_8;
 bool success_9 = false;
 if (!(std::holds_alternative<::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::STRING>>((*pos)))) {
 return {};
 }
 rule_value_STRING_8 = std::get<::ISPA_STD::Node<::Parser::Tokens, Types::rule::value::STRING>>((*pos));
 success_9 = true;
 pos++;
 if (!success_9) {
 return {};
 }
 _0 = rule_value_STRING_8;
 success_1 = true;
 break;
 }
 }
 if (!success_1) {
 return {};
 }
 Types::rule::value::pattern result;
 ::ISPA_STD::assign_compatible(result.value, _0);
 ::ISPA_STD::MatchResult<Rules, Types::rule::value::pattern, IT> match_result;
 match_result.status = true;
 match_result.node.set_data(result);
 match_result.it = pos;
 return match_result;
 }
 template<typename IT>
 auto rule_value_group(IT pos) -> ::ISPA_STD::MatchResult<Rules, Types::rule::value::group, IT>{
 ::ISPA_STD::Node<::Parser::Tokens, Types::AUTO_1> AUTO_1_0;
 bool success_1;
 ::ISPA_STD::Node<::Parser::Tokens, Types::__WS> __WS_2;
